<ng-template #fuzzalyticsPage>
  <div class="tab-page fixed">
    <div *ngIf="freshestFuzzItem" class="fuzzalytics-container">
      <app-fuzzalytics
        [fuzzItem]="freshestFuzzItem"
        [fuzzalyticsByFuzzItem]="fuzz.diagnos /* ...truncated... */
